def rep_ratio(s):
    toks = s.split()
    if not toks:
        return 0.0
    return 1.0 - len(set(toks)) / len(toks)

def ngrams(s, n=3):
    return set(s[i:i+n] for i in range(len(s)-n+1))

def jaccard(a, b):
    if not a or not b:
        return 0.0
    return len(a & b) / len(a | b)

def clean(samples):
    kept_rules = [s for s in samples
                  if 4 <= len(s) <= 60 and rep_ratio(s) <= 0.5]
    sigs, out = [], []
    for s in kept_rules:
        g = ngrams(s, 3)
        if not any(jaccard(g, prev) >= 0.5 for prev in sigs):
            sigs.append(g); out.append(s)
    return out

